picture.source:
// A library picture set on the page: fitted by its visible content and resting on the
// bottom of the module, optionally grounded by a soft shadow, with its caption directly
// under the picture rather than under the module.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const info = api.materials[d.material];
if (!info) throw Error(`素材 ${d.material} 不在作品中`);
const size = Number(d.captionSize ?? 15);
const caption = d.caption ? String(d.caption) : "";
const below = caption ? size * 1.8 : 0;
const shade = d.shadow ? Math.max(6, H * 0.05) : 0;
const room = H - below - shade * 0.6;
const k = (d.fit === "cover" ? Math.max : Math.min)(
  W / info.width,
  room / info.height,
);
const pw = Math.min(W, info.width * k),
  ph = Math.min(room, info.height * k);
const top = room - ph;
const root = api.html(
  `<div style="position:relative;width:${W}px;height:${H}px"></div>`,
).firstElementChild;
if (shade) {
  const s = document.createElement("div");
  s.style.cssText = `position:absolute;left:${(W - pw * 0.8) / 2}px;width:${pw * 0.8}px;top:${room - shade * 0.55}px;height:${shade}px;border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.2),rgba(0,0,0,.07) 60%,transparent)`;
  root.append(s);
}
const picture = api.material(d.material, {
  width: pw,
  height: ph,
  fit: d.fit ?? "contain",
  ...(d.color ? { color: d.color } : {}),
});
picture.style.position = "absolute";
picture.style.left = (W - pw) / 2 + "px";
picture.style.top = top + "px";
root.append(picture);
if (caption) {
  const c = document.createElement("div");
  c.textContent = caption;
  c.style.cssText = `position:absolute;left:-20%;right:-20%;top:${room + shade * 0.4 + size * 0.3}px;text-align:center;font-size:${size}px;line-height:1.3;color:${d.color || t.ink || "#222"};white-space:nowrap`;
  root.append(c);
}
return root;

timeline.source:
// A time axis with events: ticks on the line, dates beside it, names alternating above and
// below so neighbours never collide. Events can carry `note` and `accent`.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const size = Number(d.size ?? 14);
const font = t.font || "system-ui";
const ctx = document.createElement("canvas").getContext("2d");
const measure = (s, px, weight = 400) => {
  ctx.font = `${weight} ${px}px ${font}`;
  return ctx.measureText(String(s ?? "")).width;
};
const events = (d.events || []).map((e) => ({ ...e, at: Number(e.at) }));
const even = d.spacing === "even";
const lo = Number(d.from ?? Math.min(...events.map((e) => e.at)));
const hi = Number(d.to ?? Math.max(...events.map((e) => e.at)));
const span = hi - lo || 1;
const x0 = size * 2.5,
  x1 = W - size * 3,
  y = H / 2;
const X = (e, i) =>
  even
    ? events.length > 1
      ? x0 + (i / (events.length - 1)) * (x1 - x0)
      : (x0 + x1) / 2
    : x0 + ((e.at - lo) / span) * (x1 - x0);
const ink = t.ink || "#222",
  muted = t.muted || "#888",
  accent = t.accent || "#d97757";
const esc = (s) =>
  String(s).replace(
    /[&<>"]/g,
    (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch],
  );
let out = `<path d="M${x0 - size} ${y}H${x1 + size * 1.2}" stroke="${ink}" stroke-width="${Number(t.stroke ?? 1.6)}" stroke-linecap="round"/>`;
out += `<path d="M${x1 + size * 1.9} ${y}l${-size * 0.9} ${-size * 0.4}v${size * 0.8}z" fill="${ink}"/>`;
// Pass 1: lay out dates and record any horizontal spans where a date shifted outward.
const dateUsed = { up: -Infinity, down: -Infinity };
const shiftedDates = { up: [], down: [] };
const laid = events.map((e, i) => {
  const x = X(e, i),
    up = i % 2 === 0,
    dSide = up ? "down" : "up";
  const dateStr = String(e.date ?? e.at);
  const dw = measure(dateStr, size * 0.85);
  const dLeft = x - dw / 2 - size * 0.25,
    dRight = x + dw / 2 + size * 0.25;
  const dShift = dLeft < dateUsed[dSide] ? size * 1.05 : 0;
  dateUsed[dSide] = Math.max(dateUsed[dSide], dRight);
  if (dShift > 0) shiftedDates[dSide].push([dLeft, dRight]);
  return { e, x, up, dateStr, dShift };
});
// Pass 2: place event labels, clearing both shifted dates on the same side and sibling labels.
const used = { up: [-Infinity, -Infinity], down: [-Infinity, -Infinity] };
laid.forEach(({ e, x, up, dateStr, dShift }) => {
  const side = up ? "up" : "down",
    c = e.accent ? accent : ink;
  const tw = Math.max(
    measure(e.label ?? "", size, 600),
    e.note ? measure(e.note, size * 0.82) : 0,
  );
  const left = x - tw / 2 - size * 0.4,
    right = x + tw / 2 + size * 0.4;
  const hitsShiftedDate = shiftedDates[side].some(([a, b]) => left < b && right > a);
  const tier = left < used[side][0] ? 1 : 0;
  used[side][tier] = Math.max(used[side][tier], right);
  const baseStem = size * ((hitsShiftedDate ? 3.5 : 2.2) + (e.note ? 0.6 : 0));
  const stem = baseStem + tier * size * (e.note ? 2.8 : 1.9);
  const ty = up ? y - stem : y + stem;
  out += `<line x1="${x}" x2="${x}" y1="${y}" y2="${up ? ty + size * 0.6 : ty - size * 0.9}" stroke="${muted}" stroke-width="1"/>`;
  out += `<circle cx="${x}" cy="${y}" r="${e.accent ? 5 : 3.6}" fill="${e.accent ? accent : t.paper || "#fff"}" stroke="${c}" stroke-width="1.6"/>`;
  out += `<text x="${x}" y="${up ? y + size * 1.5 + dShift : y - size * 0.8 - dShift}" text-anchor="middle" font-size="${size * 0.85}" fill="${muted}">${esc(dateStr)}</text>`;
  out += `<text x="${x}" y="${up ? ty : ty + size * 0.2}" text-anchor="middle" font-size="${size}" font-weight="600" fill="${c}">${esc(e.label ?? "")}</text>`;
  if (e.note)
    out += `<text x="${x}" y="${up ? ty - size * 1.25 : ty + size * 1.4}" text-anchor="middle" font-size="${size * 0.82}" fill="${muted}">${esc(e.note)}</text>`;
});
return api.svg(
  `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="overflow:visible" font-family="${esc(font)}">${out}</svg>`,
);
